import argparse, json, os, sys
from simulation import run_simulation

def main():
    # Honor sandbox requirement but allow import-time skip for CI/harnesses
    if os.environ.get("SKIP_MAIN") == "1":
        return
    parser = argparse.ArgumentParser()
    parser.add_argument("--config", type=str, default=None)
    parser.add_argument("--smoke", action="store_true")
    args = parser.parse_args()
    params = {}
    if args.config:
        try:
            with open(args.config, "r") as f:
                params = json.load(f)
        except Exception as e:
            print(json.dumps({"error": f"Failed to read config: {e}"}), file=sys.stderr)
    if args.smoke:
        params.update({
            "population_size": 300,
            "time_horizon_days": 5,
            "random_seed": 42,
        })
    results = run_simulation(params)
    print(json.dumps(results))

# Execute main for both direct execution and sandbox wrapper invocation
main()

import random
from typing import List

def generate_small_world(n: int, k: int, beta: float, rng: random.Random) -> List[List[int]]:
    if n <= 1:
        return [[] for _ in range(n)]
    k = max(2, k)
    half_k = k // 2
    nbrs = [set() for _ in range(n)]
    for i in range(n):
        for d in range(1, half_k + 1):
            j = (i + d) % n
            nbrs[i].add(j); nbrs[j].add(i)
    for i in range(n):
        for j in list(nbrs[i]):
            if j > i and rng.random() < beta:
                nbrs[i].discard(j); nbrs[j].discard(i)
                candidates = [x for x in range(n) if x != i and x not in nbrs[i]]
                if candidates:
                    new_j = rng.choice(candidates)
                    nbrs[i].add(new_j); nbrs[new_j].add(i)
    return [sorted(s) for s in nbrs]
